<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\{MarketingVideoClip,MarketingVideoFilm};
use App\Services\Marketing\{MarketingClipSource,MarketingClipProduction,MarketingVideoFiles,MarketingWorkspaceFilm};
use Illuminate\Http\Request;

class MarketingWorkspaceVideoController extends Controller {
 private function project(Request $r,string $id){return app(MarketingClipSource::class)->project($id,(int)$r->user()?->id);}
 private function reply(Request $r,$p,$record,string $message){if($r->expectsJson())return response()->json(['id'=>$record->id,'status'=>$record->status]);return redirect()->route('marketing.workspace.show',['project'=>$p->id,'screen'=>$record instanceof MarketingVideoFilm?'finished':'confirmation','scene'=>$record->scene_number??null,'film'=>$record instanceof MarketingVideoFilm?$record->id:null])->with('message',$message);}
 public function quote(Request $r,string $project,MarketingClipProduction $service){$p=$this->project($r,$project);$d=$r->validate(['version'=>'required|integer','scene'=>'required|integer|min:1|max:12','request_id'=>'required|uuid','asset'=>'nullable|uuid']);$clip=$service->quote($project,$r->user()->id,$d['version'],$d['scene'],$d['request_id'],$d['asset']??null);return $this->reply($r,$p,$clip,'本段费用方案已保存，尚未提交收费生成。');}
 public function authorize(Request $r,string $project,string $clip,MarketingClipProduction $service){$p=$this->project($r,$project);$d=$r->validate(['version'=>'required|integer','consent'=>'required|accepted']);$record=$service->authorize($project,$r->user()->id,$d['version'],$clip);return $this->reply($r,$p,$record,'本段制作任务已保存。后台继续处理，不会因刷新页面重复生成。');}
 public function retry(Request $r,string $project,string $clip,MarketingClipProduction $service){$p=$this->project($r,$project);$service->retry($project,$r->user()->id,$clip);return $this->reply($r,$p,MarketingVideoClip::findOrFail($clip),'已恢复已知任务的查询或本地处理，不重新提交收费生成。');}
 public function import(Request $r,string $project,MarketingClipProduction $service){$p=$this->project($r,$project);$d=$r->validate(['version'=>'required|integer','run'=>'required|uuid','consent'=>'required|accepted']);$clip=$service->importPilot($project,$r->user()->id,$d['version'],$d['run']);return $this->reply($r,$p,$clip,'已收纳既有视频并准备本地字幕，不会重新收费生成。');}
 public function status(Request $r,string $project){$this->project($r,$project);$clips=MarketingVideoClip::where('project_id',$project)->latest('created_at')->limit(36)->get(['id','scene_number','status','error_message','updated_at']);$films=MarketingVideoFilm::where('project_id',$project)->latest('created_at')->limit(6)->get(['id','status','error_message','updated_at']);return response()->json(compact('clips','films'))->header('Cache-Control','private, no-store');}
 public function previewClip(Request $r,string $project,string $clip){$p=$this->project($r,$project);$c=MarketingVideoClip::where('project_id',$project)->where('owner_id',$r->user()->id)->findOrFail($clip);abort_unless($c->status==='completed',404);app(MarketingClipSource::class)->path($p,$c->input['image']['asset_id'],$c->input['image']['sha256']);$file=app(MarketingVideoFiles::class)->file($c->output_path,$c->output_sha256);return response()->file($file,['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function assemble(Request $r,string $project,MarketingWorkspaceFilm $service){$p=$this->project($r,$project);$d=$r->validate(['version'=>'required|integer','consent'=>'required|accepted','clips'=>'required|array|list|min:1|max:12','clips.*'=>'required|uuid|distinct']);$film=$service->prepare($project,$r->user()->id,$d['version'],$d['clips']);return $this->reply($r,$p,$film,'整片本地合成任务已保存，不重新生成视频或声音。');}
 public function retryFilm(Request $r,string $project,string $film,MarketingWorkspaceFilm $service){$p=$this->project($r,$project);$record=$service->retry($project,$r->user()->id,$film);return $this->reply($r,$p,$record,'已重新安排本地合成，不调用收费视频接口。');}
 public function approveFilm(Request $r,string $project,string $film,MarketingWorkspaceFilm $service){$p=$this->project($r,$project);$d=$r->validate(['consent'=>'required|accepted','sha256'=>'required|regex:/^[a-f0-9]{64}$/']);$record=$service->approve($project,$r->user()->id,$film,$d['sha256']);return $this->reply($r,$p,$record,'此版本已批准并保存，可以下载。没有授权发布。');}
 public function previewFilm(Request $r,string $project,string $film,MarketingWorkspaceFilm $service){$this->project($r,$project);$file=$service->preview($project,$r->user()->id,$film);return response()->file($file,['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function downloadFilm(Request $r,string $project,string $film,MarketingWorkspaceFilm $service){$this->project($r,$project);$file=$service->download($project,$r->user()->id,$film);return response()->download($file,'marketing-film-'.$film.'.mp4',['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
